function computeScaleInAiScoreFromMetrics(metric, prevMetric, holding, mktMetric) {
  try {
    const buyPrice = Number(holding.BuyPrice || holding.buyPrice || 0);
    const currPrice = Number(metric.ClosePrice || metric.close || metric.price || 0);
    const dropPct = (buyPrice > 0 && currPrice > 0) ? ((currPrice - buyPrice) / buyPrice) * 100 : -20.0;
    
    const currRsi = Number(metric.RSI || metric.rsi || 30.0);
    const prevRsi = prevMetric ? Number(prevMetric.RSI || prevMetric.rsi || currRsi) : currRsi;
    const rsiDiff5d = currRsi - prevRsi;
    
    const rawBB = metric.b_band_pct !== undefined ? metric.b_band_pct : (metric.BB_Pct !== undefined ? metric.BB_Pct : metric['BB_%b']);
    const bbPct = (rawBB !== undefined && rawBB !== null && rawBB !== '') ? Number(rawBB) : 0.05;
    
    const disparity = Number(metric.Disparity20 || metric.disparity20 || metric.disparity || 85.0);
    const vr = Number(metric.VolumeRatio || metric.volume_ratio || metric.VR || 100.0);
    const adx = Number(metric.ADX || metric.adx || 25.0);
    const minusDi = Number(metric.Minus_DI || metric.minus_di || metric.minusDi || 25.0);
    const plusDi = Number(metric.Plus_DI || metric.plus_di || metric.plusDi || 15.0);
    const macdOsc = Number(metric.MACD_Osc || metric.macd_osc || 0.0);
    const stochK = Number(metric.Stoch_K || metric.stoch_k || 20.0);
    
    let mktRet20d = 0.0, mktRsi = 50.0, mktBbPct = 0.5;
    if (mktMetric) {
      mktRsi = Number(mktMetric.RSI || mktMetric.rsi || 50.0);
      const rawMktBB = mktMetric.b_band_pct !== undefined ? mktMetric.b_band_pct : (mktMetric.BB_Pct !== undefined ? mktMetric.BB_Pct : mktMetric['BB_%b']);
      mktBbPct = (rawMktBB !== undefined && rawMktBB !== null && rawMktBB !== '') ? Number(rawMktBB) : 0.5;
      const mktDisp = Number(mktMetric.Disparity20 || mktMetric.disparity20 || 100.0);
      mktRet20d = (mktDisp - 100.0);
    }
    
    const mktRetSinceEntry = mktRet20d;
    const relRetFromEntry = dropPct - mktRetSinceEntry;
    
    const f = [
      65.0, // entry_ai_score default
      25.0, // days_from_entry default
      currRsi,
      bbPct,
      disparity,
      vr,
      vr * 1.1,
      adx,
      minusDi,
      plusDi,
      macdOsc,
      stochK,
      -5.0,
      dropPct,
      2.5,
      rsiDiff5d,
      mktRet20d * 0.25,
      mktRet20d,
      mktRsi,
      mktBbPct,
      mktRetSinceEntry,
      relRetFromEntry
    ];
    
    return predictScaleInAiScoreJs(f);
  } catch (e) {
    console.warn('Error calculating scale-in AI score:', e);
    return null;
  }
}
